svg.script:
(async function(){

const GAMES_JSON =
"https://raw.githubusercontent.com/CowGoMoo357/htmlgamesrepos/refs/heads/main/games.json";


const gamesContainer =
document.getElementById("games");

const loading =
document.getElementById("loading");

const search =
document.getElementById("search");

const categoryContainer =
document.getElementById("categories");


let games = [];
let currentCategory = "All";



async function loadGames(){

    try{

        const response =
        await fetch(GAMES_JSON);


        if(!response.ok)
            throw new Error("Failed loading games.json");


        const data =
        await response.json();


        games =
        data.games;


        createCategories();

        renderGames();


        loading.style.display="none";


    }
    catch(error){

        loading.innerHTML =
        "Unable to load games.";

        console.error(error);

    }

}




function createCategories(){

    let categories =
    [
        "All",
        ...new Set(
            games.map(
                game=>game.category
            )
        )
    ];


    categoryContainer.innerHTML="";


    categories.forEach(category=>{


        let button =
        document.createElement("button");


        button.className =
        "category";


        if(category==="All")
            button.classList.add("active");


        button.innerText =
        category;


        button.dataset.category =
        category;



        button.onclick=function(){


            document
            .querySelectorAll(".category")
            .forEach(btn=>
                btn.classList.remove("active")
            );


            button.classList.add("active");


            currentCategory =
            category;


            renderGames();


        };


        categoryContainer
        .appendChild(button);


    });

}




function renderGames(){


    gamesContainer.innerHTML="";


    let searchText =
    search.value.toLowerCase();



    let filtered =
    games.filter(game=>{


        let matchesSearch =
        game.name
        .toLowerCase()
        .includes(searchText);



        let matchesCategory =
        currentCategory==="All"
        ||
        game.category===currentCategory;



        return matchesSearch
        &&
        matchesCategory;


    });



    if(filtered.length===0){


        gamesContainer.innerHTML =
        "<h2>No games found</h2>";


        return;

    }



    filtered.forEach(game=>{


        let card =
        document.createElement("div");


        card.className =
        "card";



        card.innerHTML = `

        <img
        src="${game.icon}"
        onerror="this.style.display='none'"
        >


        <h2>
        ${game.name}
        </h2>


        <p>
        ${game.description}
        </p>


        <button class="play">
        Play
        </button>

        `;



        let play =
        card.querySelector(".play");


        play.onclick=function(){


            launchGame(game.url);


        };



        gamesContainer
        .appendChild(card);


    });


}




search.addEventListener(
"input",
renderGames
);



loadGames();



})();

async function launchGame(url){

    try{


        const response =
        await fetch(url);


        if(!response.ok)
            throw new Error("Game failed to load");


        let html =
        await response.text();



        /*
            Create a standalone game page.

            The fetched game is placed inside
            a complete HTML document so scripts,
            canvas, CSS, and assets can run.
        */

        const page = `

<!DOCTYPE html>

<html>

<head>

<meta charset="UTF-8">

<title>Scalio Game</title>


<style>

html,body{

    margin:0;
    padding:0;

    width:100%;
    height:100%;

    overflow:hidden;

    background:black;

}


iframe{

    border:0;

    width:100%;
    height:100%;

}


</style>


</head>


<body>


<iframe id="game"></iframe>



<script>


const frame =
document.getElementById("game");


frame.srcdoc =
${JSON.stringify(html)};


</script>


</body>

</html>

`;



        const dataURL =
        "data:text/html;charset=utf-8,"
        +
        encodeURIComponent(page);



        window.open(
            dataURL,
            "_blank"
        );


    }


    catch(error){


        alert(
            "Unable to launch game"
        );


        console.error(error);


    }

}
